getOutput() {
    const t = this.gridToBoundsTransform, result = [];
    for (const [connId, routes] of this.solvedRoutes ?? []) {
      const connName = this.connIdToName[connId];
      for (const route of routes) {
        const points = route.cells.map((cell) => {
          const rawX = this.gridOrigin.x + (cell.col + 0.5) * this.cellSizeMm, rawY = this.gridOrigin.y + (cell.row + 0.5) * this.cellSizeMm, tp = Ii(t, { x: rawX, y: rawY });
          return { x: tp.x, y: tp.y, z: this.layerToZ.get(cell.z) ?? cell.z };
        });
        if (points.length === 1) {
          points[0] = { ...route.startPoint };
          points.push({ ...route.endPoint });
        } else if (points.length > 1) {
          points[0] = { ...route.startPoint };
          points[points.length - 1] = { ...route.endPoint };
        }
        result.push({
          connectionName: connName,
          rootConnectionName: this.connIdToRootNet[connId],
          regionId: this.nodeWithPortPoints.capacityMeshNodeId,
          traceThickness: this.traceThickness,
          viaDiameter: this.viaDiameter,
          route: points,
          vias: route.viaCells.map((via) => {
            const rawX = this.gridOrigin.x + (via.col + 0.5) * this.cellSizeMm, rawY = this.gridOrigin.y + (via.row + 0.5) * this.cellSizeMm;
            return Ii(t, { x: rawX, y: rawY });
          })
        });
      }
    }
    return result;
  }
